const s="state",z=[{id:"state-emotion-decisions",title:"Lerner e colleghi · 2015 · Emozioni e decisioni · Dossier ST01",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Revisione narrativa di circa 35 anni di ricerca: le emozioni possono influenzare le decisioni, anche quando provengono da situazioni estranee. Gli effetti possono aiutare o danneggiare, secondo l’emozione e la decisione.",limitation:"Nessuna stima complessiva. Non convalida un meccanismo dell’umore in tre parti, un umore ottimale universale o una pausa di un minuto."},{id:"state-regulation-meta",title:"Webb, Miles e Sheeran · 2012 · Strategie di regolazione delle emozioni · Dossier ST02",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"In 306 confronti sperimentali, cambiare l’interpretazione aveva un effetto medio d = 0,36; modulare la risposta 0,16; dirigere l’attenzione 0,00. Sottocategorie e risultati emotivi differivano.",limitation:"Prevalentemente emozioni suscitate sperimentalmente, non persone in trattamento. Espressione ed esperienza dell’emozione sono diverse. Non convalida specifiche sequenze di domande o una strategia migliore per tutti."},{id:"state-acute-exercise",title:"Reed e Ones · 2006 · Una sessione di esercizio e la sensazione di energia · Dossier ST03",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 studi, 450 effetti, 13.101 partecipanti: la variazione media corretta della sensazione positiva di energia associata all’esercizio era 0,47. La variazione nel controllo era riportata separatamente: -0,17.",limitation:"Queste variazioni separate non sono un confronto randomizzato tra trattamento e controllo. Prevalentemente volontari sani, con risposte eterogenee. Non stabilisce una dose efficace di due minuti né un trattamento della depressione."},{id:"state-exercise-mental-health",title:"Singh e colleghi · 2023 · Attività fisica e disagio · Dossier ST04",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"97 revisioni, con 1.039 studi randomizzati distinti e oltre 128.119 partecipanti, hanno trovato riduzioni medie dei sintomi. Gli effetti mediani per depressione e ansia erano -0,43 e -0,42.",limitation:"77 revisioni erano di qualità criticamente bassa. Programmi lunghi differiscono da movimenti brevi. L’effetto -0,60 sul disagio proveniva da una revisione di sei studi con 508 partecipanti; un altro piccolo studio non era significativo."},{id:"state-facial-feedback",title:"Coles, Larsen e Lench · 2019 · Feedback facciale · Dossier ST05",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 studi e 286 effetti: d complessivo = 0,20, intervallo di confidenza al 95% da 0,14 a 0,26, riunendo esperienza emotiva e giudizi affettivi. Effetti piccoli e variabili.",limitation:"Il numero pubblicato è 138, non 136. Alcuni effetti sui giudizi mostravano segnali di distorsione legata alla pubblicazione. Non dimostra che sorridere tratti il disagio in modo affidabile."},{id:"state-cyclic-sighing",title:"Balban e colleghi · 2023 · Brevi pratiche respiratorie · Dossier ST09",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adulti assegnati casualmente, reclutati soprattutto in un corso universitario di psicologia di Stanford, praticavano cinque minuti al giorno per 28 giorni. Il modello statistico favoriva la respirazione per le emozioni positive.",limitation:"Studio esplorativo, registrato retrospettivamente. Non dimostra superiorità per l’ansia, efficacia di due respiri, durata dei benefici o efficacia terapeutica."},{id:"state-affect-labeling",title:"Lieberman e colleghi · 2007 · Dare un nome alle emozioni · Dossier ST11",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 adulti sani davano un nome alle emozioni sui volti durante una scansione cerebrale. Usare parole emotive, rispetto a nomi propri associati al genere, mostrava una differenza in una misura dell’amigdala: d riportato = 0,79.",limitation:"Non misurava il recupero dal disagio soggettivo. Non dimostra benefici di parole più lievi, del nominare le proprie emozioni, sollievo duraturo dai sintomi o efficacia di questa scheda."},{id:"state-gratitude-expressed",title:"Kirca, Malouff e Meynadier · 2023 · Gratitudine espressa · Dossier ST13",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 studi e 25 campioni randomizzati: per il benessere positivo, g = 0,22 rispetto ai controlli neutri. Rispetto ad altre attività credibili, g = 0,12, con intervallo di confidenza che include zero.",limitation:"I totali dei partecipanti nell’articolo sono discordanti: non riportiamo un numero preciso. Non convalida una routine mattutina completa, immagini di scene future o superiorità ad alternative credibili."},{id:"state-positive-self-statements",title:"Wood e colleghi · 2009 · Affermazioni positive su di sé · Dossier ST12",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"I primi esperimenti con studenti universitari suggerivano risposte diverse alle frasi positive ripetute secondo l’autostima, comprese possibili risposte peggiori per alcuni partecipanti.",limitation:"Le successive repliche non hanno riprodotto i risultati su umore, autostima momentanea o moderazione. Non sono dimostrati né beneficio né danno universali. Nessuna prova di superiorità delle formule pronunciate con enfasi."},{id:"state-mental-contrasting",title:"Wang, Wang e Gai · 2021 · Raggiungere gli obiettivi · Dossier ST15",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 articoli, 24 effetti indipendenti, 15.907 partecipanti: contrasto mentale e pianificazione della risposta mostravano g = 0,336. La stima corretta per la distorsione di pubblicazione era inferiore: 0,242.",limitation:"Studi eterogenei e possibile distorsione di pubblicazione. Non convalida immagini del processo Dickens, vergogna, rigidi obblighi o una superiorità causale del formato di proposta."},{id:"state-self-compassion-motivation",title:"Breines e Chen · 2012 · Motivazione a migliorare · Dossier ST16",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Quattro esperimenti brevi sostenevano la compatibilità tra compassione e motivazione a migliorare. Dopo un test andato male, il tempo medio di studio era 306,5 secondi contro 203,2 senza promemoria.",limitation:"I risultati al secondo test non differivano significativamente; il confronto con l’autostima era inconcludente. Non dimostra cambiamento duraturo, riparazione effettiva o efficacia del processo Dickens."},{id:"state-nhs-panic",title:"NHS · Disturbo di panico · Dossier ST18",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Episodi ricorrenti di panico inatteso richiedono una valutazione professionale. Tra i trattamenti consolidati ci sono terapia cognitivo-comportamentale e farmaci.",limitation:"Indicazioni, non uno studio sull’efficacia del coaching. ODA non diagnostica il panico né presume che dolore toracico nuovo, svenimento o difficoltà respiratorie inspiegate siano ansia innocua. Cerca assistenza medica o d’emergenza appropriata."},{id:"state-affirmation-replication",title:"Flynn e Bordieri · 2020 · Repliche sulle affermazioni positive · Dossier ST20",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Due esperimenti con studenti universitari in contesti non clinici non hanno riprodotto i precedenti risultati sull’umore, sull’autostima momentanea o sul ruolo moderatore dell’autostima stabile nelle affermazioni positive.",limitation:"Risultati nulli non dimostrano equivalenza né risolvono ogni dubbio sulle frasi. Due repliche fallite lasciano incerti i benefici precedenti e le differenze legate all’autostima."}];function i(e){const a=e.suggestions;return{schemaVersion:2,revision:2,id:e.id,courseId:s,locale:"it",title:e.title,goal:e.goal,minutes:{learning:6,suggestedAction:a.minutes[0],review:2},direction:{hook:e.hook,reason:{id:`${e.id}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:e.reasons},why:{id:`${e.id}-why`,label:"A cosa serve questo passo nella tua settimana?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${e.id}-cost`,label:"Quanto ti costa continuare a fare come adesso?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:e.invitation,instructions:e.instructions,prompts:[],suggestions:a,suggested:{action:a.action[0],minimum:a.minimum[0],minutes:a.minutes[0],cueHint:a.cue[0],placeHint:a.place[0],obstacleHint:e.obstacle,fallbackHint:a.fallback[0],observationHint:a.observation[0]},stopRule:e.stop,accessibleAlternative:e.accessible},result:{question:e.result,observationPrompt:e.observation},judgment:{primary:e.scenario},carry:{takeaway:e.takeaway,followUp:{questionId:`${e.id}-return`,question:e.follow,observationPrompt:e.followObservation,adjustmentPrompt:"Che cosa renderebbe il prossimo tentativo adatto alla tua vita?"}},goDeeper:{sections:e.depth,sourceIds:e.sources}}}const l=i({title:"Non trascinare un litigio nella prossima conversazione",goal:"Riconosci da dove viene l’emozione, poi fai una richiesta utile in sicurezza.",hook:"Il litigio di prima ti brucia ancora? Dai alla prossima richiesta una possibilità tutta sua.",reason:"Quanto pesa la conversazione di prima su quella che ti aspetta?",reasons:["Chiedere chiaramente a casa","Proteggere un rapporto di lavoro","Non trascinare un litigio nel successivo"],paragraphs:["Una sensazione può arrivare da un’altra situazione. L’irritazione dopo un turno difficile può pesare sulla richiesta di una riparazione a casa. Le emozioni possono influenzare decisioni estranee a ciò che le ha provocate. Non sono per questo sbagliate. Chiediti da dove vengono.","Per questo corso scegli un momento che si ripete: prima di una chiamata, un messaggio o un lavoro che conta per te. Dai un nome alla sensazione e alla sua probabile origine. Poi fai un passo utile, senza pretendere calma. Se la rabbia segnala un danno reale, ascoltala. Chiedere, proteggerti o cercare supporto può contare più del cambiare umore."],example:{title:"Daria chiede una riparazione",text:"Alle 18 Daria rientra irritata dopo un turno teso. Il rubinetto perde. Si accorge che il proprietario di casa non c’entra con il litigio al lavoro. Seduta al tavolo della cucina, invia una richiesta chiara. Lui chiede una foto. Daria annota la richiesta e manda la foto, ancora irritata."},invitation:"Nel momento che hai scelto, fai una richiesta utile. Riconosci la sensazione, poi usa la tua frase.",instructions:["Chiediti dove può essere nata la sensazione.","Fai una richiesta chiara in un contesto sicuro."],suggestions:{action:["Invia una richiesta chiara di riparazione","Chiedi un chiarimento che ti serve","Chiedi un aiuto concreto"],minimum:["Invia una frase con la richiesta","Fai una domanda precisa","Indica un bisogno di supporto"],cue:["Prima del prossimo messaggio necessario","Alla prossima occasione sicura per parlarne"],place:["Seduto al tavolo della cucina","In una conversazione scritta sicura"],fallback:["Usa un messaggio scritto sicuro","Scegli un’occasione sicura più avanti"],observation:["La mia richiesta e la risposta ricevuta","Se ho fatto la richiesta"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Penso ancora alla conversazione precedente",stop:"Se c’è un pericolo reale, fermati e cerca protezione o supporto.",accessible:"Tieni gli occhi aperti. Resta seduto, osserva la stanza e usa il tuo abituale modo di comunicare.",result:"Hai fatto la richiesta che avevi scelto?",observation:"Che cosa hai chiesto e quale risposta hai ricevuto?",scenario:{scenario:"Tra due minuti scade il termine per prenotare la riparazione. Dopo un turno teso, Daria vuole far sistemare la perdita questa settimana. Il proprietario ha risposto ragionevolmente in passato.",question:"Come può dare alla richiesta una buona partenza?",options:[{text:"Prendersi cinque minuti per riordinare le idee, poi inviare la richiesta basata sui fatti chiedendo una data per la riparazione.",feedback:"Una pausa definita può aiutare a organizzare la richiesta. Qui farebbe scadere il termine, mentre il messaggio è già fattibile. Daria può chiedere una data partendo dai fatti anche se l’irritazione resta.",id:"pause-then-request"},{text:"Descrivere subito la perdita con un messaggio breve e lasciare che sia il proprietario a proporre il passo successivo.",feedback:"Il messaggio descrive bene il problema e arriva in tempo. Ma non chiarisce quando serve la riparazione. Chiedere una data rende visibile il bisogno di questa settimana, senza pretendere che il proprietario accetti.",id:"describe-without-date"},{text:"Riconoscere l’irritazione rimasta dal turno, descrivere la perdita e chiedere chiaramente una data per la riparazione.",feedback:"Così distingue la sensazione dai fatti di questa conversazione. Daria fa la richiesta necessaria e può annotare la risposta. Sentirsi calma e ottenere l’accordo del proprietario non sono condizioni per averla fatta.",id:"name-and-request"}],id:"state-1-carryover-request",bestOptionId:"name-and-request"},takeaway:"Controlla da dove viene la sensazione. Affronta la prossima richiesta partendo dai suoi fatti.",follow:"Riconoscere l’emozione rimasta da prima ha cambiato la richiesta, anche se l’umore è rimasto uguale?",followObservation:"Che cosa è cambiato nella richiesta o nell’umore? Entrambi possono essere rimasti uguali.",depth:[{heading:"Le emozioni passano da una decisione all’altra",paragraphs:["Lerner e colleghi hanno esaminato circa 35 anni di ricerca su emozioni e decisioni. Descrivono le emozioni incidentali: sensazioni nate altrove che influenzano un nuovo giudizio. Le emozioni possono aiutare una decisione oppure ostacolarla. La domanda utile è se questa sensazione ti informa sulla situazione presente o rispecchia qualcosa accaduto prima. Non serve stabilire un umore ideale per tutti. Serve capire quale informazione stai usando per decidere adesso. [ST01: state-emotion-decisions]","Questa distinzione non ti chiede di ignorare rabbia, tristezza o preoccupazione. Un insulto ripetuto, un bisogno irrisolto e un turno faticoso sono fatti diversi. Guarda gli elementi attuali prima di scegliere come rispondere. Se serve una riparazione, chiedila. Se serve protezione, scegli quella. Qui usiamo una richiesta quotidiana per rendere chiara la scelta. Il corso non dimostra che riconoscere l’emozione precedente la cambi, garantisca collaborazione o risolva un rapporto pericoloso."]},{heading:"Una prova che continua, senza esami sull’umore",paragraphs:["Durante il corso mantieni un momento ricorrente e una direzione che conta nella tua vita. Le prossime lezioni propongono uno strumento solo quando le tue annotazioni indicano un problema a cui potrebbe servire. Non devi accumulare sette obblighi. Osserva che cosa hai chiesto, iniziato, cambiato o interrotto in quel momento. L’umore può restare uguale e un messaggio senza risposta può comunque contenere una richiesta fatta.","Webb e colleghi hanno riunito 306 confronti sperimentali sulle strategie di regolazione delle emozioni. Cambiare un’interpretazione ha mostrato benefici medi, ma strategie e risultati variavano. Alcuni risultati riguardavano l’espressione, altri l’esperienza dell’emozione. Nascondere una sensazione non prova che sia scomparsa. Questi confronti di laboratorio non convalidano la triade corpo, attenzione e linguaggio né questo breve esercizio ODA. [ST02: state-regulation-meta] Annota pochi fatti, poi scegli il prossimo tentativo in base alla risposta e alle tue circostanze."]}],id:"state-1",sources:["state-emotion-decisions","state-regulation-meta"]}),c=i({title:"L’energia non arriva? Prova il lavoro che conta",goal:"Nel momento già scelto, prova una preparazione confortevole e fai una parte utile del lavoro.",hook:"Ti sei mosso, ma la carica non è arrivata. Puoi comunque fare il prossimo piccolo lavoro?",reason:"Quale lavoro aspetta? Quando ti sarebbe più utile recuperare?",reasons:["Iniziare secondo le mie possibilità","Fare un passo nel mio lavoro","Lasciare spazio al recupero"],paragraphs:["Una sessione di esercizio aerobico può aumentare in media la sensazione di energia. È diverso dalla ricerca sui programmi di attività fisica e sui sintomi clinici. Nessuno dei due dimostra che due minuti bastino a cambiare l’umore in modo affidabile.","Mantieni momento e lavoro già scelti. Se muoverti è adatto alle tue possibilità, prova un’opzione confortevole lasciando invariati musica e postura. Poi fai il minimo del lavoro, se appropriato. Potrebbero servirti riposo o un segnale senza movimento. Annota separatamente la preparazione e ciò che hai fatto nel lavoro. Aver fatto una cosa non prova che sia avvenuta anche l’altra."],example:{title:"Marco scrive la prima slide",text:"Alle 9 Marco si sente spento prima di preparare una presentazione. Fa una passeggiata breve e confortevole, senza accendere la musica. Alla scrivania l’energia è uguale. Scrive comunque una frase utilizzabile nella slide e annota entrambi i fatti. La slide richiede altro lavoro. La prossima volta proverà a iniziare da seduto."},invitation:"Nello stesso momento, prova una preparazione confortevole se serve. Poi fai il minimo del tuo lavoro.",instructions:["Scegli uno strumento, oppure mantieni la preparazione abituale senza movimento.","Fai una parte utile del lavoro, secondo le tue possibilità."],suggestions:{action:["Scrivi una frase utilizzabile","Correggi un piccolo errore nel lavoro","Invia la richiesta chiara che hai scelto"],minimum:["Scrivi una frase utilizzabile","Correggi un elemento concreto","Invia una frase con la richiesta"],cue:["Dopo un movimento confortevole facoltativo","Nel momento già scelto per il lavoro"],place:["Seduto al mio piano di lavoro","Nel mio spazio di lavoro accessibile"],fallback:["Inizia da seduto senza movimento","Riposa e scegli un’altra occasione"],observation:["La preparazione e il lavoro svolti","Se muovermi mi ha dato fastidio"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"L’energia resta bassa dopo la preparazione",stop:"Interrompi il movimento se dà fastidio. Scegli riposo o supporto quando serve.",accessible:"Puoi muoverti da seduto, osservare la stanza a occhi aperti o iniziare senza movimento. Non serve sorridere.",result:"Hai fatto il minimo utile del tuo lavoro?",observation:"Quale preparazione e quale lavoro hai svolto davvero?",scenario:{scenario:"Dopo una passeggiata confortevole, Marco ha la stessa energia e nessun fastidio. Ha verificato i dati della slide e riesce a scrivere una frase. Gli restano tre minuti.",question:"Quale passo rende utile la prova?",options:[{text:"Impiegare due minuti per sistemarsi e iniziare da seduto, poi scrivere la frase della slide nel minuto rimasto.",feedback:"Iniziare da seduto può servire quando muoversi dà fastidio o per ragioni di accessibilità. Marco non segnala questi problemi. Un’altra preparazione consuma quasi tutto il tempo, senza affrontare un ostacolo emerso.",id:"timed-seated-start"},{text:"Scrivere la frase utilizzabile, annotare l’energia invariata e valutare un’altra preparazione confortevole per la prossima prova.",feedback:"Il lavoro può iniziare anche senza il cambiamento di energia sperato. Marco osserva la preparazione provata e se ha iniziato. Potrà adattarla più avanti, senza aumentare lo sforzo per forzare un miglioramento dell’umore.",id:"task-and-record"},{text:"Chiedere a un collega conferma del dato già verificato, poi scrivere una frase provvisoria mentre aspetta la risposta.",feedback:"Una bozza e un secondo controllo aiutano quando i dati sono incerti. Qui sono già verificati. Chiedere conferma aggiunge l’attesa di una risposta, mentre Marco può scrivere e annotare una frase utilizzabile adesso.",id:"check-and-draft"}],id:"state-2-unchanged-energy",bestOptionId:"task-and-record"},takeaway:"Valuta la preparazione con sincerità. Per il lavoro, guarda che cosa hai fatto davvero.",follow:"La preparazione ti ha aiutato a iniziare, ha dato fastidio o ha indicato un bisogno di riposo?",followObservation:"Descrivi aiuto, fastidio, bisogno di recupero o nessuna differenza evidente, separatamente dall’esito del lavoro.",depth:[{heading:"Energia momentanea e trattamento sono domande diverse",paragraphs:["Reed e Ones hanno riunito 158 studi con 13.101 partecipanti su singole sessioni di esercizio aerobico. La variazione media associata all’esercizio era 0,47 per l’affettività positiva attivata, cioè sensazioni come energia e prontezza. La variazione nella condizione di controllo era riportata separatamente. Lo 0,47 non è quindi un effetto terapeutico ottenuto dal confronto randomizzato tra esercizio e controllo. Risposte individuali e procedure degli studi variavano. [ST03: state-acute-exercise]","Quel risultato non prova l’efficacia di due minuti, un aumento affidabile di energia per tutti o un trattamento della depressione. Una distinta sintesi di programmi più lunghi ha trovato riduzioni medie dei sintomi, ma molte delle revisioni incluse erano di qualità criticamente bassa. [ST04: state-exercise-mental-health] La tua breve preparazione è una prova personale facoltativa. Adattala ad accessibilità, salute ed energie disponibili. Se emergono stanchezza o fastidio, cambiare strumento, chiedere supporto o proteggere il recupero può servire alla tua direzione più che prolungare l’esercizio."]},{heading:"Le aggiunte facoltative possono restare facoltative",paragraphs:["Per iniziare il lavoro non servono un sorriso, una posa espansiva o una certa canzone. Coles e colleghi hanno esaminato 138 studi e 286 effetti. La stima complessiva del feedback facciale era piccola, 0,20, e riuniva esperienza emotiva e giudizi. Gli effetti variavano; alcuni giudizi mostravano segnali di distorsione legata alla pubblicazione. Non dimostra che sorridere sia una risposta affidabile al disagio. [ST05: state-facial-feedback] Nella tua preparazione non c’è posto per un sorriso imposto.","In questa prova che prosegue, cambia una preparazione alla volta e mantieni riconoscibile il lavoro utile. Lascia normali le altre condizioni. Se aggiungi insieme musica, postura e movimento, poi dovrai indovinare che cosa ha funzionato. Un’osservazione personale può aiutarti a scegliere un’altra prova; non isola un meccanismo biologico né dimostra un rapporto di causa ed effetto. Se il prossimo lavoro è ancora alla tua portata, puoi farne il minimo senza più energia. Se serve recupero, annota quella scelta senza pretendere un umore migliore."]}],id:"state-2",sources:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}),u=i({title:"Troppa tensione? Fermati senza inseguire la calma",goal:"Scegli una pausa confortevole, poi rispondi come previsto o fai un passo per chiedere supporto.",hook:"La mail aspetta mentre continui con gli esercizi? Fermati e scegli una risposta ponderata.",reason:"Che cosa aiuterebbe una pausa? Che cosa rimanderebbe?",reasons:["Rispondere con più attenzione","Rispettare il segnale per fermarmi","Chiedere un supporto utile"],paragraphs:["Lo studio sui sospiri prevedeva cinque minuti al giorno per 28 giorni. Non ha verificato che due respiri diano calma immediata. Una pausa respiratoria dolce è preparazione facoltativa, non l’azione utile che hai scelto.","Torna al momento e alla risposta previsti. Siediti al sicuro. Puoi respirare normalmente a occhi aperti, osservando la stanza. Se confortevole, inspira dolcemente, aggiungi una piccola inspirazione ed espira lentamente senza forzare. Fermati per capogiri, formicolio, affanno o fastidio. Poi scegli risposta, riposo o supporto adatti. Sintomi fisici nuovi e gravi richiedono valutazione medica, non spiegazioni basate sullo stress."],example:{title:"Lea sceglie una pausa confortevole",text:"Dopo pranzo Lea è alla scrivania, tesa per una mail non urgente. Concentrarsi sul respiro dà fastidio. Tiene gli occhi aperti e osserva il telaio della finestra. Poi invia una richiesta di chiarimento basata sui fatti. La preoccupazione resta; la risposta non arriva. Annota la pausa in cui ha osservato ciò che la circondava e la frase inviata, senza dichiarare riuscito un esercizio respiratorio."},invitation:"Prima della risposta scelta, fai una pausa confortevole. Puoi respirare normalmente e osservare la stanza.",instructions:["Resta seduto: evita guida, acqua e rischi di caduta.","Dopo la pausa, fai il minimo della risposta se appropriato."],suggestions:{action:["Rispondi con una frase ponderata","Chiedi un chiarimento che ti serve","Fai una richiesta di supporto"],minimum:["Invia una frase basata sui fatti","Fai una domanda chiara","Indica un bisogno di supporto"],cue:["Dopo una pausa confortevole facoltativa","Prima della prossima risposta non urgente"],place:["Seduto al sicuro alla scrivania","Seduto in privato, al sicuro"],fallback:["Osserva la stanza respirando normalmente","Fermati e scegli come chiedere supporto"],observation:["Se la pausa era confortevole; la risposta data","Se ho rispettato i segnali per fermarmi"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Concentrarmi sul respiro mi dà fastidio",stop:"Fermati per capogiri, formicolio, affanno o fastidio. Riprendi a respirare normalmente. Un dolore toracico nuovo e forte o difficoltà respiratorie inspiegate richiedono una valutazione medica.",accessible:"Tieni gli occhi aperti, resta seduto, osserva un oggetto neutro e lascia il respiro normale.",result:"Hai dato la risposta che avevi scelto?",observation:"Che cosa era confortevole e quale risposta hai dato davvero?",scenario:{scenario:"Lea interrompe la prova respiratoria e torna a respirare normalmente, da seduta. Lo stordimento persiste ed è nuovo per lei. La mail non è urgente; un collega vicino può aiutarla.",question:"Che cosa deve cambiare adesso?",options:[{text:"Restare seduta respirando normalmente, rimandare la mail e chiedere al collega aiuto per ottenere un parere medico.",feedback:"Ha fatto bene a fermarsi. Il sintomo persiste ed è nuovo per lei: chiedere aiuto tempestivo viene prima della mail o di un altro strumento. Sintomi gravi o pericolo immediato richiedono soccorsi d’emergenza.",id:"stop-and-support"},{text:"Restare seduta respirando normalmente, osservare il telaio della finestra e poi valutare di nuovo la situazione prima di rispondere.",feedback:"Osservare ciò che ti circonda può sostituire l’attenzione al respiro se questa ti dà fastidio. Qui il sintomo nuovo persiste dopo l’interruzione. Osservare un oggetto non deve ritardare la richiesta di aiuto e di un parere medico appropriato.",id:"stop-and-look-outward"},{text:"Restare seduta respirando normalmente, rimandare la mail a domani e controllare più tardi se lo stordimento è passato.",feedback:"Rimandare una mail non urgente lascia spazio alle cure. Ma non affronta un sintomo nuovo che persiste. Chiedi aiuto appropriato adesso, senza rimandare anche la valutazione medica insieme al messaggio.",id:"stop-and-defer"}],id:"state-3-uncomfortable-pause",bestOptionId:"stop-and-support"},takeaway:"Fermarti in sicurezza dà informazioni utili. Non serve calma per rispondere con attenzione.",follow:"La pausa era confortevole? Ha aiutato la risposta o indicato che serviva un altro strumento?",followObservation:"Descrivi se la pausa era confortevole, eventuali interruzioni o bisogni di supporto, separatamente dalla risposta successiva.",depth:[{heading:"Che cosa ha verificato lo studio sui sospiri",paragraphs:["Balban e colleghi hanno assegnato casualmente 108 adulti a brevi pratiche respiratorie o alla mindfulness. La pratica durava cinque minuti al giorno per 28 giorni. La maggior parte proveniva da un corso universitario di psicologia di Stanford. Lo studio era esplorativo e registrato dopo il suo avvio. Il modello statistico favoriva la respirazione per le emozioni positive. Non dimostrava una superiorità per l’ansia né un risultato affidabile dopo due respiri. [ST09: state-cyclic-sighing]","Il sospiro ciclico studiato prevedeva un’inspirazione lenta, una seconda più breve e un’espirazione lenta, da seduti o sdraiati. Qui proponiamo una prova facoltativa confortevole e alternative con respiro normale. Sono adattamenti ODA per sicurezza e accessibilità. Non riempire o svuotare i polmoni fino a sforzarti, non trattenere il respiro e non accelerare per forzare un effetto. Nelle annotazioni puoi distinguere la preparazione, una prova interrotta e la risposta inviata. Una non sostituisce le altre."]},{heading:"Un esercizio respiratorio non spiega un sintomo",paragraphs:["Un esercizio di respirazione non ti dice perché sia comparso un sintomo fisico. Le indicazioni NHS raccomandano una valutazione professionale per episodi ricorrenti di panico inatteso e descrivono trattamenti consolidati. Il limite del corso è chiaro: ODA offre educazione, non diagnosi o trattamento. Non presumere che dolore toracico insolito, svenimento o difficoltà respiratorie inspiegate siano ansia innocua. Sintomi nuovi e gravi richiedono una valutazione medica; un pericolo immediato richiede soccorsi d’emergenza. [ST18: state-nhs-panic]","Puoi scegliere una risposta pratica senza cambiare il respiro. Tieni gli occhi aperti, osserva un oggetto neutro, resta seduto o chiedi supporto. Se la pausa aumenta il fastidio, lasciala perdere: insistere non equivale a progredire. Non devi ottenere calma prima di una richiesta utile quando il contesto è sicuro e il passo è alla tua portata. Non devi nemmeno continuare con la richiesta se riposo, protezione o aiuto umano sono la scelta appropriata adesso."]}],id:"state-3",sources:["state-cyclic-sighing","state-nhs-panic"]}),p=i({title:"Continui a rimuginare? Fai una domanda utile",goal:"Trasforma una domanda sulla tua situazione ricorrente in un’azione utile o una richiesta di supporto appropriata.",hook:"Continui a chiederti perché, senza scoprire nulla. Quale risposta cambierebbe i prossimi dieci minuti?",reason:"Che cosa rimandi continuando a ripensare a questa situazione?",reasons:["Chiarire un problema reale","Usare quello che ho imparato","Smettere di rimandare una richiesta utile"],paragraphs:["Una domanda serve quando la risposta cambia una scelta. Chiedere perché può rivelare una causa, una competenza da imparare o chi deve rimediare. Non è automaticamente dannoso. Ma ripercorrere la situazione senza nuove informazioni può non cambiare ciò che farai dopo.","Nel momento già scelto, chiediti che cosa richiede un chiarimento, un cambiamento o supporto. Dai alla risposta un verbo: inviare, correggere, chiedere, riposare. La ricerca confronta strategie ampie, non questa sequenza di domande. Usala come aiuto pratico e segui la risposta se è fattibile. Poi annota il comportamento, senza confonderlo con quanto incoraggianti suonavano le parole."],example:{title:"Omar trova chi deve approvare",text:"Alle 14 Omar esamina alla scrivania una richiesta di progetto bloccata. Chiedersi perché rivela che manca l’approvazione del budget, non un suo fallimento. Trova il referente negli appunti e manda una domanda di chiarimento. Nessuna risposta arriva quel pomeriggio. Annota domanda, messaggio e approvazione irrisolta, senza scrivere altre domande motivanti."},invitation:"Fai una domanda utile sulla stessa situazione. Esegui il più piccolo passo appropriato suggerito dalla risposta.",instructions:["Continua a verificare cause e responsabilità quando serve.","Trasforma la risposta in una richiesta o correzione concreta."],suggestions:{action:["Invia una richiesta di chiarimento utile","Correggi un problema individuato nel lavoro","Chiedi una risorsa che manca"],minimum:["Invia una frase per chiedere chiarimenti","Sistema un elemento concreto","Indica una risorsa che manca"],cue:["Dopo aver risposto alla mia domanda utile","Nel momento già scelto per il lavoro"],place:["Alla scrivania o al telefono","In una conversazione scritta sicura"],fallback:["Chiedi aiuto per trovare la risposta","Scegli un’occasione adatta per rispondere"],observation:["La risposta e l’azione svolta","Che cosa resta irrisolto"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Continuo ad analizzare senza fare un passo",stop:"Non sostituire protezione o supporto necessari con un altro esercizio di riflessione.",accessible:"Rispondi in silenzio o con il tuo modo abituale di comunicare. Chiedere supporto può essere l’azione utile.",result:"Hai seguito la risposta con un’azione utile?",observation:"Che cosa ha chiarito la domanda e che cosa hai fatto?",scenario:{scenario:"Omar ha verificato che la richiesta contiene tutti i dati del budget necessari, ma non è mai arrivata al responsabile dell’approvazione. Il referente indicato può ricevere domande adesso.",question:"Come può dare seguito alla domanda?",options:[{text:"Ricontrollare i dati del budget prima di inviare la domanda di chiarimento, così il responsabile riceverà una richiesta completa.",feedback:"Controllare i dati obbligatori può evitare un messaggio inutile. Omar li ha già verificati: manca l’invio al referente. Ripetere il controllo aggiunge preparazione senza risolvere il problema che ha individuato.",id:"check-budget-field"},{text:"Fare cinque minuti di pausa, poi inviare la domanda di chiarimento tenendo separata la frustrazione dal messaggio basato sui fatti.",feedback:"È una pausa con un termine, utile se serve davvero. Qui questo bisogno non è emerso. La domanda basata sui fatti è pronta e affronta direttamente l’approvazione mancante: Omar può inviarla adesso.",id:"break-then-contact"},{text:"Inviare al referente indicato una domanda basata sui fatti, poi annotare la risposta ricevuta oppure la sua assenza.",feedback:"Così trasforma la causa individuata in un’azione che può compiere. La risposta potrebbe non arrivare e l’approvazione dipende da altri. Omar può comunque annotare se ha fatto la richiesta utile.",id:"contact-approver"}],id:"state-4-question-to-action",bestOptionId:"contact-approver"},takeaway:"Una risposta serve quando ti aiuta a cambiare il prossimo passo utile.",follow:"La domanda ha chiarito qualcosa e cambiato la tua azione, oppure suonava soltanto incoraggiante?",followObservation:"Che cosa hai chiarito o cambiato? Va bene anche non aver scoperto o cambiato nulla.",depth:[{heading:"Gli studi sull’attenzione non convalidano queste domande",paragraphs:["Webb e colleghi hanno riunito 306 confronti sperimentali. Le strategie che cambiavano l’interpretazione mostravano un effetto medio di 0,36 sui risultati emotivi. Le strategie che dirigevano l’attenzione avevano una media complessiva vicina a zero, ma le sottocategorie differivano. Queste categorie comprendevano istruzioni diverse ed emozioni brevi suscitate sperimentalmente. Non provano che specifiche domande del mattino migliorino l’umore, né che chiedersi perché o concentrarsi su un problema sia in generale dannoso. [ST02: state-regulation-meta]","Usa questa distinzione per capire a che cosa serve una domanda. Indagare può stabilire i fatti. Chiarire le responsabilità può individuare chi deve intervenire. Pianificare può rivelare una risorsa mancante. Ciascuna cosa può meritare tempo. Se la risposta indica un comportamento fattibile, sceglilo. Se indica un vincolo esterno, non trasformarlo in un problema di atteggiamento. Questa coppia di domanda e azione è un adattamento ODA, non un protocollo verificato con una durata efficace o un risultato emotivo promesso."]},{heading:"Collega la risposta alla prova che stai facendo",paragraphs:["La tua prova ha già una direzione, un momento ricorrente e una risposta utile. Tienili presenti. La domanda deve migliorare la risposta, senza diventare un nuovo rito quotidiano. Una richiesta di chiarimento può raggiungere chi deve approvare; un passo di lavoro può correggere l’elemento sbagliato; una scelta di protezione può affrontare un’interazione dannosa. Cerca soltanto informazioni pertinenti alla prossima decisione. Non devi risolvere tutto per rendere utile una domanda.","Le emozioni possono influenzare come interpreti una risposta e provenire da un altro evento. Lerner e colleghi descrivono effetti sia utili sia dannosi delle emozioni sulle decisioni. [ST01: state-emotion-decisions] Annota gli elementi raccolti e ciò che hai fatto davvero. Una risposta utile può lasciare irrisolto il problema più grande. Se non potevi agire in sicurezza, annota il vincolo o scegli supporto. Una pausa ponderata non è un fallimento; una domanda scritta non prova che l’azione successiva sia avvenuta."]}],id:"state-4",sources:["state-regulation-meta","state-emotion-decisions"]}),d=i({title:"Quel messaggio ferisce. Non cambiare i fatti",goal:"Distingui un fatto da un’intenzione ipotizzata, poi chiedi chiarimenti o proteggiti nella stessa situazione ricorrente.",hook:"Quel messaggio ti ha ferito. Prima di indovinare l’intenzione, guarda le parole e scegli una risposta sicura.",reason:"Che cosa proteggeresti con una risposta più sicura? Quale sarebbe il costo?",reasons:["Usare le critiche senza attaccarmi","Smettere di accettare trattamenti ingiusti","Chiedere prima di indovinare l’intenzione"],paragraphs:["Un evento e una spiegazione sono diversi. “Il messaggio contiene un insulto” è un fatto verificabile. “Vuole rovinarmi la carriera” attribuisce un’intenzione. Un’altra spiegazione deve rispettare i fatti, senza rendere innocuo un danno reale.","Nel momento già scelto, indica un fatto e ciò che non sai. Poi chiedi chiarimenti, correggi, metti un limite o cerca supporto. Parole emotive più lievi non sono automaticamente più vere. Lo studio classico misurava risposte cerebrali ai volti, non il sollievo ottenuto rinominando il disagio. Cerca accuratezza, senza imporre ottimismo."],example:{title:"Nina conserva i messaggi",text:"Alle 16 Nina riceve un altro messaggio offensivo nel gruppo di lavoro. Seduta in un luogo privato, distingue le parole salvate dalle sue ipotesi sull’intenzione di chi scrive. È ancora arrabbiata. Chiede a un responsabile fidato come segnalare il problema in sicurezza, senza definirlo un malinteso. Lui deve verificare. Nina annota la richiesta e conserva i messaggi."},invitation:"Usa i fatti per scegliere la risposta. Chiarisci l’incertezza o proteggiti se il danno è documentato.",instructions:["Distingui i fatti osservabili dalle intenzioni ipotizzate.","Chiedi chiarimenti, correggi, metti un limite o chiedi supporto, secondo il caso."],suggestions:{action:["Chiedi come ricevere supporto in sicurezza","Invia un chiarimento basato sui fatti","Correggi un errore di lavoro verificato"],minimum:["Fai una richiesta di supporto","Fai una domanda sui fatti","Correggi un elemento concreto"],cue:["Dopo aver controllato un messaggio doloroso","Prima della prossima risposta prevista"],place:["Seduto in privato, al sicuro","Nel mio canale di supporto fidato"],fallback:["Conserva le prove e cerca supporto sicuro","Scegli un’altra occasione sicura per rispondere"],observation:["Il fatto considerato e la risposta data","Quali prove hanno cambiato la mia interpretazione"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Una spiegazione positiva nasconderebbe un danno reale",stop:"Non reinterpretare abusi o pericoli come malintesi. Scegli protezione e supporto.",accessible:"Indica i fatti in silenzio, scrivendo, nella lingua dei segni o con assistenza. Non serve concentrarti sul corpo né usare parole più lievi.",result:"Hai dato la risposta basata sui fatti che avevi scelto?",observation:"Quali elementi hai usato e quale risposta hai dato?",scenario:{scenario:"Nina ha conservato al sicuro messaggi con insulti ripetuti. Un responsabile fidato è disponibile adesso; il portale per le segnalazioni apre domani. Non c’è pericolo immediato e l’intenzione resta sconosciuta.",question:"Quale passo usa i fatti e il supporto disponibile?",options:[{text:"Creare un’altra copia protetta degli insulti già salvati, poi aspettare che il portale per le segnalazioni apra domani.",feedback:"Conservare le prove aiuta a proteggersi. Questi messaggi sono già al sicuro: un’altra copia non aggiunge una tutela necessaria. Il responsabile disponibile può chiarire subito come procedere in sicurezza, senza contattare chi ha scritto.",id:"copy-and-wait"},{text:"Distinguere gli insulti documentati dalle intenzioni ipotizzate, poi chiedere a una persona fidata come ricevere supporto in sicurezza.",feedback:"Mantiene incerta l’intenzione e riconosce il danno reale. Nina può cercare protezione senza dimostrare un’intenzione nascosta, cambiare il nome dell’emozione o affrontare direttamente chi ha inviato quei messaggi offensivi.",id:"facts-and-support"},{text:"Evitare il contatto con chi scrive, aspettare il portale di domani e usare i messaggi salvati per chiedere supporto.",feedback:"Evitare il contatto diretto e usare un canale di segnalazione può proteggere. Qui un supporto fidato è disponibile prima. Chiedere adesso come procedere mantiene aperte le possibilità, senza obbligare a segnalare o affrontare qualcuno.",id:"wait-safe-portal"}],id:"state-5-documented-insults",bestOptionId:"facts-and-support"},takeaway:"Cambia l’interpretazione solo fin dove arrivano le prove. Poi dai la risposta appropriata.",follow:"Quali prove hanno confermato o messo in dubbio l’interpretazione? La tua risposta era adatta?",followObservation:"Indica il fatto rilevante, l’incertezza rimasta e se la risposta rispettava le prove.",depth:[{heading:"Una misura cerebrale non è un trattamento",paragraphs:["Lieberman e colleghi hanno studiato 30 adulti sani che davano un nome alle emozioni sui volti durante una scansione cerebrale. La condizione con parole emotive differiva da quella con nomi propri associati al genere in una misura dell’amigdala. Lo studio non mostrava che sostituire “furioso” con “infastidito” riduca il disagio quotidiano, che nominare la propria emozione produca lo stesso effetto o che un beneficio duri. [ST11: state-affect-labeling] Sono interventi e risultati diversi, che non possiamo scambiare.","Qui controlliamo fatto, sensazione e incertezza come aiuto ODA per rendere esplicita la prossima scelta. Puoi usare una parola intensa ma accurata, non dare un nome alla sensazione o tenere privata la nota. Un insulto documentato resta un insulto anche se più tardi sei meno arrabbiato. Una breve risposta in ritardo può restare ambigua anche se adesso provi molta ansia. Usa ciò che puoi verificare, lascia sconosciuto ciò che non sai e scegli secondo sicurezza e direzione."]},{heading:"Rivalutare può anche voler dire mettere un limite",paragraphs:["Cambiare un’interpretazione viene spesso chiamato rivalutazione cognitiva. Webb e colleghi hanno trovato benefici medi in confronti sperimentali diversi, con differenze chiare tra strategie e risultati. Questo non rende una spiegazione positiva sempre preferibile. Le prove non convalidano questa precisa scheda da un minuto e non giustificano il trascurare critiche, vincoli materiali o danni. [ST02: state-regulation-meta] Una nuova interpretazione deve lasciare visibili i fatti difficili, anche quando il tuo stato d’animo cambia.","Un’interpretazione equa può rendere specifica la responsabilità: ho sbagliato questo elemento, quindi lo correggo. Può anche ridurre accuse senza prove: non so perché la risposta tarda, quindi chiedo. Se il danno è documentato, può sostenere la protezione: non devo dimostrare un’intenzione prima di chiedere aiuto. Prosegui la stessa prova annotando quale risposta hai dato e quali elementi sono emersi. Una richiesta senza risposta resta tale. Fermarti in sicurezza resta una scelta valida. Non serve una storia più ottimista per rendere accettabili queste annotazioni."]}],id:"state-5",sources:["state-affect-labeling","state-regulation-meta"]}),m=i({title:"Le frasi positive suonano false? Fai qualcosa di utile",goal:"Usa una frase credibile per iniziare il lavoro già scelto, senza pretendere gratitudine o un umore diverso.",hook:"La routine del mattino è pronta. Ti ha già fatto iniziare qualcosa di concreto?",reason:"Che cosa rimandi allungando la routine?",reasons:["Iniziare l’azione che ho scelto","Usare parole in cui credo","Tenere breve la preparazione"],paragraphs:["Ripetere grandi affermazioni positive non è un metodo dimostrato per migliorare l’umore di tutti. I primi risultati, sia di beneficio sia di peggioramento, non sono stati riprodotti nelle successive repliche. Qui non ci sono prove verificate che una voce energica o formule ripetute risolvano il problema. Scegli un’istruzione semplice che puoi seguire.","Nel momento già scelto, prova “Posso fare una richiesta chiara anche se ho dubbi”, poi inviala se appropriato. Se scegli la gratitudine, descrivi qualcosa di reale, non un traguardo immaginato. Saltala se forzata. La frase è preparazione. Annota a parte il comportamento: non servono una sensazione convincente o un rito completo."],example:{title:"Amina fa la prima richiesta",text:"Dopo il primo caffè delle 8, Amina ha due minuti prima di uscire. “Sono inarrestabile” suona falso. Sceglie “Posso fare una domanda chiara anche con dei dubbi” e invia la richiesta rimandata. Oggi salta la gratitudine. Nessuna risposta arriva prima dell’uscita. Annota la frase inviata, senza giudicare l’incertezza come un fallimento."},invitation:"Tieni breve la routine: una frase credibile, poi l’azione utile già scelta.",instructions:["Scegli una frase su un comportamento che puoi controllare.","Prova l’azione adesso se appropriato, oppure salva il segnale concreto per iniziare."],suggestions:{action:["Invia la richiesta chiara che hai scelto","Scrivi una frase utile per il lavoro","Chiedi un aiuto concreto"],minimum:["Invia una frase chiara","Scrivi una frase utilizzabile","Indica un bisogno di supporto"],cue:["Dopo la prima bevanda della giornata","Nel momento già scelto per il lavoro"],place:["Seduto al tavolo della cucina","Nel mio abituale spazio di lavoro"],fallback:["Salta il rito e usa la frase","Scegli la prossima occasione realistica"],observation:["Se alle parole è seguita l’azione","Quale preparazione ha ritardato l’azione"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Continuo ad allungare la preparazione",stop:"Salta gratitudine, immagini o frasi che aumentano il disagio. Scegli invece un supporto ordinario.",accessible:"Respira normalmente e osserva a occhi aperti. Pronuncia, scrivi, usa la lingua dei segni o segui l’istruzione in silenzio.",result:"Dopo la frase, hai fatto l’azione scelta?",observation:"Che cosa hai iniziato, inviato o cambiato davvero?",scenario:{scenario:"Amina ha due minuti prima di uscire. La domanda verificata è chiara, cortese e pronta su un canale sicuro. Continua a rimandare perché vuole sembrare sicura di sé.",question:"Quale versione è adatta a questa mattina?",options:[{text:"Provare il messaggio ad alta voce per novanta secondi, poi inviare la domanda verificata prima di uscire di casa.",feedback:"Una prova a tempo aiuta una richiesta poco chiara o nuova. Questa domanda è già chiara e verificata. La prova occupa quasi tutto il tempo disponibile senza affrontare l’idea che serva sicurezza prima di agire.",id:"rehearse-and-send"},{text:"Usare un’istruzione credibile sul chiedere anche con dei dubbi, poi inviare la domanda pronta attraverso il canale sicuro.",feedback:"Collega parole su un comportamento controllabile a un’azione disponibile. Amina non deve credere a una grande promessa, sentirsi grata o eliminare i dubbi prima di fare la sua richiesta utile.",id:"credible-and-send"},{text:"Scrivere una breve apertura e una chiusura per il messaggio, poi inviare la domanda pronta prima di uscire.",feedback:"Apertura e chiusura aggiungono cortesia quando serve. La domanda pronta comunica già la richiesta. Rifinirla ancora lascia meno tempo per inviarla; un’istruzione credibile affronta direttamente l’iniziare anche con dei dubbi.",id:"polish-and-send"}],id:"state-6-believable-start",bestOptionId:"credible-and-send"},takeaway:"Scegli parole abbastanza credibili da usarle. Lascia che l’azione dia la prova.",follow:"La frase ti ha aiutato ad agire, ha ritardato il passo o non ha fatto una differenza evidente?",followObservation:"Descrivi aiuto o ritardo separatamente dall’esito dell’azione; nessuna differenza evidente è una risposta valida.",depth:[{heading:"Le prove sulle affermazioni positive sono contrastanti",paragraphs:["Wood e colleghi hanno studiato la ripetizione di frasi positive su di sé in campioni universitari. I primi risultati suggerivano risposte diverse secondo l’autostima, compreso un peggioramento per alcuni partecipanti. Due successive repliche di Flynn e Bordieri non hanno riprodotto i risultati sull’umore, sull’autostima momentanea o sul ruolo moderatore dell’autostima. Il limite corretto è questo: prove contrastanti, senza sostenere che le affermazioni aiutino tutti o danneggino tutti. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","Le prove non stabiliscono che formule ripetute con il corpo e la voce siano una soluzione. Qui un’istruzione credibile su un comportamento è un aiuto pratico, non un trattamento psicologico dimostrato. Puoi usare parole tue, saltare la frase o scegliere supporto. Mantieni chiari il lavoro e il minimo, così da poterli osservare. Pronunciare una frase su un’azione futura è preparazione. Inviare la richiesta, correggere un elemento o chiedere supporto è l’azione che potrai riferire dopo."]},{heading:"Apprezzare qualcosa ha limiti e resta facoltativo",paragraphs:["Kirca e colleghi hanno esaminato 23 studi con 25 campioni randomizzati sulla gratitudine espressa. Il benessere positivo mostrava un piccolo beneficio medio rispetto ai controlli neutri, con un effetto di 0,22. Rispetto ad altre attività credibili per il benessere, la stima era più piccola e statisticamente inconcludente. [ST13: state-gratitude-expressed] L’attività di confronto conta quindi nel valutare il beneficio apparente. Una differenza non significativa non prova che tutte le attività siano equivalenti.","Quella ricerca non dimostra l’efficacia di una routine da dieci minuti, di tre scene future immaginate, di una sequenza mattutina ottimale o una superiorità al trattamento clinico appropriato. Se vuoi apprezzare qualcosa, scegli un dettaglio reale gradito. Non cercare a forza un lato positivo in una perdita né gratitudine verso qualcuno pericoloso. Un futuro desiderato è una possibilità, non un ricordo o un risultato raggiunto. La prova pratica è se la preparazione facoltativa sostiene la stessa azione utile. Eliminala se aggiunge ritardo o fastidio."]}],id:"state-6",sources:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}),v=i({title:"Basta nuove routine. Che cosa merita un’altra settimana?",goal:"Usa le prove annotate per mantenere, ridurre, sostituire o sospendere lo stesso esperimento la prossima settimana.",hook:"La routine cresce e il lavoro aspetta. Quale parte ti ha aiutato a iniziare e quale ti ha rallentato?",reason:"A che cosa rinunceresti continuando questa prova la prossima settimana?",reasons:["Mantenere il prossimo passo utile","Proteggere il recupero necessario","Lasciare un rito che mi rallenta"],paragraphs:["Un futuro desiderato, collegato a un ostacolo e a un piano di risposta, ha prove più dirette delle immagini di conseguenze catastrofiche. I costi immaginati sono previsioni, non fatti. Non servono vergogna o promesse più severe.","Rivedi le annotazioni dello stesso momento. Quale preparazione ha sostenuto la risposta utile? Quale ha causato fastidio, ritardo o nessuna differenza evidente? Mantieni una versione utile, cambia un problema o sospendi. Adatta il minimo della prossima settimana alle tue possibilità e prova un passo appropriato, se fattibile. Riposo, protezione e supporto possono far parte del piano."],example:{title:"Enrico riduce il passo",text:"Domenica pomeriggio Enrico rivede alla scrivania le prove per iniziare il portfolio. Una pausa per osservare ciò che aveva intorno lo ha aiutato a iniziare; un lungo rito lo ha rallentato due volte. Oggi ha dormito male: salta il rito e corregge una didascalia. Prevede lo stesso piccolo passo martedì. Il portfolio è incompleto, ma il prossimo piano rispetta i fatti."},invitation:"Rivedi la stessa prova. Mantieni una versione utile e prova il minimo fattibile.",instructions:["Rivedi i tentativi; gli esiti mancanti restano sconosciuti.","Per la prossima settimana mantieni, riduci, cambia o sospendi una versione."],suggestions:{action:["Ripeti un passo utile del lavoro","Fai la prossima richiesta chiara","Fai il passo che hai scelto per recuperare"],minimum:["Correggi un elemento utile del lavoro","Usa una frase per la richiesta","Prenditi il tempo di recupero scelto"],cue:["Nel momento già provato che mi aiuta","Alla prossima occasione realistica"],place:["Nel mio abituale spazio per il lavoro","Nel luogo scelto per recuperare"],fallback:["Riduci il passo secondo le tue possibilità","Fai una pausa e scegli supporto"],observation:["Che cosa ho ripetuto o cambiato","Quale ostacolo si è presentato davvero"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Il piano abituale chiede più di quanto posso fare",stop:"Salta le immagini di conseguenze che ti provocano disagio. Riposo, protezione e supporto possono essere passi appropriati.",accessible:"Rivedi in silenzio o con assistenza. Per una pausa, resta seduto a occhi aperti, senza movimento.",result:"Hai fatto il prossimo minimo che avevi scelto?",observation:"Che cosa hai mantenuto, cambiato o sospeso? Che cosa è successo davvero?",scenario:{scenario:"Dopo aver dormito male, Enrico ha cinque minuti utilizzabili. La didascalia contiene un errore noto, con la correzione pronta. La scadenza è la prossima settimana; preparativi lunghi hanno ritardato gli ultimi due inizi.",question:"Quale versione rispetta gli elementi raccolti?",options:[{text:"Correggere una didascalia del portfolio, annotare il tentativo ridotto e scegliere la prossima sessione secondo le proprie possibilità.",feedback:"Mantiene lo scopo e adatta la quantità a oggi. Enrico può usare le annotazioni per scegliere un’altra occasione senza pretendere un lungo rito o un livello perfetto di energia prima di iniziare.",id:"small-caption"},{text:"Usare i cinque minuti per ordinare gli appunti della prossima sezione, lasciando la correzione già nota della didascalia a martedì.",feedback:"Ordinare appunti prepara una sezione futura, ma i preparativi hanno già ritardato il lavoro utile. La correzione è pronta. Completare quella piccola parte verifica una versione che affronta l’ostacolo annotato.",id:"sort-next-section"},{text:"Rimandare la correzione a domani, quando sarà riposato, usando questi cinque minuti per fissare un momento in cui ricontrollarla.",feedback:"Rimandare serve se la stanchezza rende inadatto il lavoro o l’accuratezza richiede controlli. Qui la correzione è pronta e fattibile. Pianificare un’altra verifica rinvia una parte significativa che può fare adesso.",id:"defer-for-checking"}],id:"state-7-capacity-review",bestOptionId:"small-caption"},takeaway:"Mantieni lo scopo. Lascia che tentativi reali e possibilità attuali guidino la prossima versione.",follow:"La prossima versione era alla tua portata? Quale ostacolo l’ha influenzata davvero?",followObservation:"Indica che cosa funzionava, cosa ostacolava il passo o perché servivano recupero o cambiamenti.",depth:[{heading:"Pianifica l’ostacolo senza immaginare catastrofi",paragraphs:["Wang e colleghi hanno riunito 24 effetti indipendenti in 21 articoli con 15.907 partecipanti. Il contrasto mentale unito alla pianificazione della risposta aveva un effetto medio tra piccolo e medio sul raggiungimento degli obiettivi, pari a 0,336. La stima corretta per possibili distorsioni di pubblicazione era inferiore e i risultati variavano. La procedura collega un futuro desiderato fattibile, un ostacolo e un piano: se compare l’ostacolo, farò questo. Non convalida il processo Dickens, l’induzione di vergogna o il trasformare ogni “dovrei” in “devo”. [ST15: state-mental-contrasting]","Scegli un ostacolo sostenuto dalle annotazioni o dalle circostanze. Se è interno, indica una risposta gestibile. Se è esterno, potrebbero servire risorse, un contesto diverso o aiuto. Un costo futuro immaginato resta una previsione. Non devi rivivere ricordi dolorosi o immaginare danni crescenti per rendere valido il piano. Il metodo più breve basato sulle annotazioni è un adattamento ODA. La sua durata è una stima, non un tempo ottimale verificato."]},{heading:"Consolida la prova senza aggiungere un altro rito",paragraphs:["Il corso è iniziato con un momento ricorrente e una risposta utile. Rivedi quei precisi tentativi prima di scegliere che cosa merita un’altra settimana. Distingui una preparazione provata da un lavoro completato e una sensazione invariata da un minimo non fatto. Un’annotazione mancante non dice quale sia stato l’esito. Se il momento previsto non si è presentato, puoi indicarlo. Lascia che ogni scelta successiva risponda a ciò che sai davvero.","Breines e Chen hanno trovato che la compassione verso di sé può coesistere con la motivazione a migliorare in esperimenti brevi. Dopo un test andato male, il gruppo con compassione studiava più a lungo di quello senza promemoria. I risultati al secondo test non differivano significativamente; il confronto con l’autostima era inconcludente. [ST16: state-self-compassion-motivation] Puoi quindi lasciar cadere l’idea che il disprezzo sia necessario per impegnarti. Non garantisce un cambiamento duraturo. La prossima versione può includere supporto, recupero o l’interruzione di un piano inadatto. Annotazioni e ritorno con una data tengono chiare queste scelte, senza una serie quotidiana obbligatoria."]}],id:"state-7",sources:["state-mental-contrasting","state-self-compassion-motivation"]}),g=[{id:"state-1",practiceCount:3,correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"Un uomo attraversa una tranquilla strada cittadina sotto alberi illuminati dal sole"}},{id:"state-2",practiceCount:3,correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"Una donna cammina su una passerella tra piante verdi"}},{id:"state-3",practiceCount:3,correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"Una donna a occhi chiusi si abbraccia dolcemente in un bosco"}},{id:"state-4",practiceCount:3,correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"Una donna con un berretto di maglia rivolta al sole basso"}},{id:"state-5",practiceCount:3,correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"Un uomo fermo davanti a una finestra luminosa"}},{id:"state-6",practiceCount:3,correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"Una donna seduta sull’erba guarda verso il sole del mattino"}},{id:"state-7",practiceCount:3,correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"Una donna seduta su una roccia all’aperto scrive su un quaderno"}}];function f(e,a){const o=g[a],n=e.judgment.primary.options.find(t=>t.id===e.judgment.primary.bestOptionId),r=e.judgment.primary.options.filter(t=>t.id!==n.id).map(t=>t.text);return r.splice(o.correct,0,n.text),{id:o.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.suggested.action,"Annota l’esito reale e scegli il prossimo tentativo appropriato."].slice(0,o.practiceCount),reflection:e.direction.reason.label,question:`${e.judgment.primary.scenario} ${e.judgment.primary.question}`,options:r,correct:o.correct,feedback:n.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:o.photo}}const b={id:"state",title:"Tensione addosso? Scegli il prossimo passo",subtitle:"7 lezioni. Prova una risposta utile, con strumenti facoltativi per il momento che la precede.",description:"Scegli un momento che si ripete nella tua giornata. Preparati senza forzarti, guarda i fatti, agisci e verifica com’è andata. Mantieni ciò che ti aiuta senza pretendere un umore migliore.",scope:"Per adulti che cercano strumenti quotidiani per cambiare umore ed energia. È educazione, non diagnosi o trattamento. Non tratta disturbi d’ansia, disturbo di panico o depressione e non sostituisce terapia o farmaci. Interrompi subito qualsiasi esercizio respiratorio in caso di capogiri, stordimento, formicolio o affanno. Torna a respirare normalmente e siediti. Se hai problemi cardiaci o polmonari, oppure sei incinta, consulta un professionista sanitario prima di provare pratiche respiratorie energizzanti. Non praticarle mai mentre guidi o sei in acqua. In caso di crisi o pensieri di farti del male, contatta il numero di emergenza locale: 911 negli Stati Uniti, 112 in Italia, Turchia e gran parte d’Europa.",outcome:"Una risposta utile in un momento ricorrente, annotazioni sincere dei tentativi e un piano per la prossima settimana adatto alle tue possibilità.",photo:{id:"1500080628126-901233e80205",alt:"Una donna su un pontile di legno nell’ora dorata, con una mano alzata verso la luce"},lang:"it",lessons:[l,c,u,p,d,m,v].map(f)};export{b as COURSE,z as SOURCES,l as STATE_1_V2,c as STATE_2_V2,u as STATE_3_V2,p as STATE_4_V2,d as STATE_5_V2,m as STATE_6_V2,v as STATE_7_V2};
